#!/bin/bash
# Compilation du coeur natif en ARM64 (Android arm64-v8a) sur le PORTABLE (-O2 par defaut).
#   laptop_arm64_port_build.sh [PORT_OPT]
set -e
H=admin@192.168.1.124
S="C:/Users/Admin/Downloads/RE4 PROJECT/re4-decomp-upstream"
OPT="${1:--O2}"
ssh -o ConnectTimeout=8 $H "mkdir -p /c/re4n/re4port"
tar cf - -C "$S" --exclude=./.git --exclude=./_port_build --exclude=./_port_build_x86 --exclude=./_port_build_x86_64 --exclude=./_port_build_arm64 --exclude=./_port_build_ios --exclude=./_port_dbg . | ssh $H "cd /c/re4n/re4port && tar xf - 2>/dev/null"
python "$(dirname "$0")/casse_tar.py" "$S" | ssh $H "cd /c/re4n/re4port && tar xf - && sed -i 's|\"tools/|\"tools_lc/|g' config/G4BE08/modules.py && grep -rl \"#include \\\"tools/\" src include | xargs -r sed -i 's|#include \"tools/|#include \"tools_lc/|g'"
ssh $H "cd /c/re4n/re4port && find port src include -mmin -600 -type f -exec touch {} + 2>/dev/null; true"
ssh -o ServerAliveInterval=15 $H "cd /c/re4n/re4port && T0=\$(date +%s) && export NDK=C:/android/android-ndk-r26d PORT_OPT='$OPT' PORT_ABI=arm64 && /c/Python314/python port/build_game.py --jobs 12 --quiet > /c/re4n/re4port_dol_arm64.log 2>&1; tail -1 /c/re4n/re4port_dol_arm64.log; /c/Python314/python port/build_rel.py --jobs 12 > /c/re4n/re4port_rel_arm64.log 2>&1; tail -3 /c/re4n/re4port_rel_arm64.log; B=/c/android/android-ndk-r26d/toolchains/llvm/prebuilt/windows-x86_64/bin; L=C:/re4n/android-arm64-v8a-m1; \$B/clang++.exe --target=aarch64-none-linux-android24 -DNJ_DEVTOOLS=1 -DNJ_MOBILE=1 -DNJ_NO_WATCH -DANDROID -DNDEBUG -IC:/re4n/nj-m1/runtime/include -IC:/re4n/nj-m1/runtime/third_party/zstd -I\$L/_deps/sdl2-build/include -I\$L/_deps/sdl2-build/include/SDL2 -O2 -std=gnu++20 -funwind-tables -c port/njgfx/njgfx.cpp -o _port_build_arm64/njgfx.o > /c/re4n/re4port_njgfx_arm64.log 2>&1 || { echo pont_en_echec; head -20 /c/re4n/re4port_njgfx_arm64.log; }; RE4_EXTRA_LINK=\"_port_build_arm64/njgfx.o \$L/runtime/libnjruntime.a \$L/runtime/libnj_imgui.a \$L/_deps/sdl2-build/libSDL2.a -lOpenSLES -lGLESv1_CM -lm -ldl @port/gxn_wrap.rsp\" /c/Python314/python port/build_game.py --link --quiet --jobs 12 > /c/re4n/re4port_build_arm64.log 2>&1; \$B/aarch64-linux-android28-clang++.cmd @_port_build_arm64/game.rsp -o _port_build_arm64/re4 -lEGL -lGLESv3 -llog -landroid -static-libstdc++ -Wl,--error-limit=0 _port_build_arm64/njgfx.o \$L/runtime/libnjruntime.a \$L/runtime/libnj_imgui.a \$L/_deps/sdl2-build/libSDL2.a -lOpenSLES -lGLESv1_CM -lm -ldl -Wl,--allow-multiple-definition -Wl,--wrap=memset -Wl,--wrap=calloc -Wl,--wrap=malloc @port/gxn_wrap.rsp > /c/re4n/re4port_link_arm64.log 2>&1; R=\$?; grep -E \"error\" /c/re4n/re4port_link_arm64.log | sort -u | head -10; echo \"build=\$R duree=\$(( \$(date +%s) - T0 )) s\"; tail -12 /c/re4n/re4port_build_arm64.log | cut -c1-220; ls -la _port_build_arm64/re4 2>&1"

